
window.onload = function () {

    // Get student data generated by the C program
    const state = studentState;

    // Check whether student data was loaded successfully
    if (!state || !state.success) {

        document.getElementById("error").textContent =
            state ? state.error : "Student data could not be loaded.";

        return;
    }

    const student = state.student;

    // Display student information
    document.getElementById("welcome").textContent =
        "Welcome, " + student.firstName + " " + student.lastName + "!";

    document.getElementById("studentName").textContent =
        student.firstName + " " + student.lastName;

    document.getElementById("studentId").textContent =
        student.userId;

    document.getElementById("gradeLevel").textContent =
        student.gradeLevel;

    document.getElementById("studentGpa").textContent =
        student.gpa;

    // Display grades
    showGrades();

    // Display attendance
    showAttendance();

    // Display assignments
    showAssignments();

    // Display announcements
    showAnnouncements();
};


function showGrades() {

    const list = document.getElementById("gradeList");

    list.innerHTML = "";

    state.grades.forEach(g => {

        list.innerHTML += `
            <tr>
                <td>${g.course}</td>
                <td>${g.score}</td>
            </tr>
        `;
    });

    if (state.grades.length === 0) {

        list.innerHTML =
            "<tr><td colspan='2'>No grades available.</td></tr>";
    }
}


function showAttendance() {

    const list = document.getElementById("attendanceList");

    list.innerHTML = "";

    state.attendance.forEach(a => {

        list.innerHTML += `
            <tr>
                <td>${a.course}</td>
                <td>${a.status}</td>
            </tr>
        `;
    });

    if (state.attendance.length === 0) {

        list.innerHTML =
            "<tr><td colspan='2'>No attendance available.</td></tr>";
    }
}


function showAssignments() {

    const list = document.getElementById("assignmentList");

    list.innerHTML = "";

    // Assignments are loaded from the database state
    const records = state.assignments || [];

    records.forEach(a => {

        list.innerHTML += `
            <tr>
                <td>${a.course}</td>
                <td>${a.assignmentName}</td>
                <td>${a.dueDate}</td>
            </tr>
        `;
    });

    if (records.length === 0) {

        list.innerHTML =
            "<tr><td colspan='3'>No assignments available.</td></tr>";
    }
}


function showAnnouncements() {

    const list = document.getElementById("announcementList");

    list.innerHTML = "";

    state.announcements.forEach(a => {

        list.innerHTML += `
            <h3>${a.title}</h3>
            <p>${a.date}</p>
            <p>${a.message}</p>
            <hr>
        `;
    });

    if (state.announcements.length === 0) {

        list.innerHTML =
            "No announcements available.";
    }
}
